  "julian-content-lab-4": {
    "sections": [
      {
        "heading": "学习增长，需要什么样的练习",
        "kind": "source",
        "paragraphs": [
          "这期节目由Nat采访Julian和Asher，讨论他们如何进入增长领域、为何难以找到合适的增长人才，以及结构、数据和指导如何帮助学习。章节也列出测试广告所需的钱与时间、订阅电商案例和分析工具。",
          "节目把原则与具体工作放在一起：知道渠道名称，并不等于能设计一次测试；掌握工具操作，也不代表理解不同受众为何购买。两位来宾的经历为这种区分提供了背景。"
        ]
      },
      {
        "heading": "编辑分析：把学习预算写进实验设计",
        "kind": "analysis",
        "paragraphs": [
          "新手第一次投放时，可以先问，这笔钱准备买到什么知识。如果目标是比较两种需求表述，就应保持受众和后续页面尽量一致；如果同时换人群、价格和页面，即使结果不同，也很难解释原因。",
          "预算不应只设一个花完即止的数字。还需要记录准备工作、素材制作和复盘时间，并约定什么情况暂停。这样，即便短期没有带来订单，也能判断实验是否回答了原来的问题。"
        ]
      },
      {
        "heading": "编辑分析：训练质量看能否做出下一版",
        "kind": "analysis",
        "paragraphs": [
          "判断一门训练是否有用，可以观察学员是否完成真实项目，反馈是否指出具体选择，以及修改之后能否解释为何更合适。漂亮的课程目录和大量工具截图，都不能单独回答这些问题。",
          "例如，要求学员为同一产品写两个面向不同受众的开头，再请潜在用户比较理解程度。这个任务会暴露定位和表达上的盲点。反馈越贴近真实任务，越容易把知识转为可反复使用的能力。"
        ]
      }
    ],
    "takeaway": "编辑提炼：学习增长的单位应是能复盘的实验与作品，而不仅是听完的课程。",
    "practice": "原创编辑练习：为正在学的技能选择一个真实小项目，列出可观察的完成标准，以及一次能改变下一版的反馈。",
    "references": [
      {
        "title": "发布方节目简介、日期与详细章节",
        "url": "https://music.amazon.ca/podcasts/68ede3d1-6933-443d-93e5-77a931e27951/episodes/a931612d-c64e-4c9e-b06c-1146c4286487/the-content-lab-4-learning-growth-with-julian-shapiro-and-asher-king-abramson-demand-curve"
      }
    ]
  },
  "julian-skio-growth-funnels": {
    "sections": [
      {
        "heading": "先决定把有限资源放在哪里",
        "kind": "source",
        "paragraphs": [
          "Skio的这篇文字访谈按渠道识别与渠道测试展开。Julian建议研究同类企业如何增长，再优先测试较有把握的方向；也讨论哪些营销工作更适合内部积累，哪些可以借助专业外部团队。",
          "他把文案与品牌核心知识联系起来，同时提醒团队考虑达到渠道所需能力的难度。判断外包与否，因而既涉及时间和成本，也涉及对产品的理解。这是文字访谈，原页未提供可靠发布日期。"
        ]
      },
      {
        "heading": "编辑分析：不要只比较报价",
        "kind": "analysis",
        "paragraphs": [
          "外包决策可以列成三项：完成任务需要什么能力、内部达到该能力要多久、任务中有多少知识必须长期留在团队。一次特殊视频制作与每周持续修改产品说明，往往不会得到相同答案。",
          "交给外部团队后，内部仍需要有人定义受众、审核事实和解释结果。否则，交付可能按时完成，但企业并不知道为何有效，也无法判断下一轮应该保留什么。这种判断工作不能随着合同一起消失。"
        ]
      },
      {
        "heading": "编辑分析：把测试结果变成内部资产",
        "kind": "analysis",
        "paragraphs": [
          "无论由谁执行，都应保留测试目标、素材版本、受众范围、花费和后续转化。仅保存一份月报汇总，可能丢掉决定下一步的细节。给结果附上一句解释，也记录尚不能确定的部分。",
          "研究竞品时同样要避免把历史成功当成现成答案。渠道成本、产品阶段和受众环境都可能不同。更好的产物是一组有依据的测试顺序，再用本公司的用户和经济性验证。"
        ]
      }
    ],
    "takeaway": "编辑提炼：外包执行可以加速，企业仍需要保留对受众、事实和结果的判断。",
    "practice": "原创编辑练习：选择一项准备外包的工作，写出验收标准、内部负责人，以及交付后必须留存的一份知识记录。",
    "references": [
      {
        "title": "Skio原始文字访谈",
        "url": "https://skio.com/interviews/designing-zero-to-one-growth-funnels-with-julian-shapiro"
      }
    ]
  },
