        "heading": "延伸理解（编辑分析）",
        "kind": "analysis",
        "paragraphs": [
          "比较方案时要重新获取当前价格，也要记录服务不可用时的备用安排。共享服务能够降低部分固定投入，但可靠性、隐私和等待也有成本。适合自己的方案，应在常用场景中持续方便。"
        ]
