  "naval-r20261117-nothing-over": {
    "sections": [
      {
        "heading": "小团队采用什么沟通结构",
        "kind": "source",
        "paragraphs": [
          "纳瓦尔描述一家规模较小的公司：一位联合创始人担任 CEO 与产品协调者，其他成员可以直接交流。它依靠成员自主导航，避免增加过多管理层级。"
        ]
      },
      {
        "heading": "AI 辅助的是跨领域接口",
        "kind": "source",
        "paragraphs": [
          "他举例用 AI 阅读复杂代码、研究材料和供应商文件，帮助定位知识与搭建临时分析。硬件、软件和 AI 成员也可以借工具完成部分相邻领域工作，减少等待。"
        ]
      },
      {
        "heading": "明确仍没有答案的问题",
        "kind": "source",
        "paragraphs": [
          "谈话随后提出模型行业会集中还是分散、开源处境和新型模型等问题。纳瓦尔承认没有确定答案；目录保留这种开放状态，不将问题改写成他的成功预测。"
        ]
      }
    ],
    "takeaway": "AI 可能改变协作接口，但团队结构与行业未来依然需要具体判断。",
    "references": [
      {
        "title": "Naval 官方网站｜原始页面",
        "url": "https://nav.al/over"
      }
    ]
  },
  "naval-r20261117-return-code": {
    "sections": [
      {
        "heading": "启动成本下降，重新动手",
        "kind": "source",
        "paragraphs": [
          "纳瓦尔谈自己理解计算机原理，却多年不再认真写代码。过去连接服务、基础设施和新工具的启动成本很高，代理的进步使他愿意重新制作完整的小应用。"
        ]
      },
      {
        "heading": "从大众商店到个人应用",
        "kind": "source",
        "paragraphs": [
          "他设想软件可以围绕个人需求生成，而不必每个应用都面向庞大市场。对应用商店与手机平台的判断由此出现；这些是2026年对变化方向的推测，并非既成结果。"
        ]
      },
      {
        "heading": "代理仍需要人的判断",
        "kind": "source",
        "paragraphs": [
          "节目继续比较模型的不同用途与迎合用户的倾向。代理能生成成果，不表示作者可以省略审查；对软件、平台和业务价值的判断，仍贯穿这场讨论。"
        ]
      }
    ],
    "takeaway": "代理降低了制作个人软件的门槛，也让分发与判断问题重新浮现。",
    "references": [
      {
        "title": "Naval 官方网站｜原始页面",
        "url": "https://nav.al/code"
      },
      {
        "title": "Naval 2026-03-23 X原帖（官网逐条引用，直连本轮403）",
        "url": "https://x.com/naval/status/2036285641462595898"
      }
    ]
  },
  "naval-r20261117-motorcycle-mind": {
    "sections": [
      {
        "heading": "从实际使用而非旁观进入",
        "kind": "source",
        "paragraphs": [
          "Naval 与 Nivi 从 AI 推文进入工作问题，强调通过动手了解工具。节目讨论编码代理与产品管理之间的联系：人提出想做的东西，再与系统反复沟通。"
        ]
      },
      {
        "heading": "工作名称与能力可能分离",
        "kind": "source",
        "paragraphs": [
          "他们追问传统软件工程、模型训练和用语言描述需求会怎样改变分工，也讨论平均化输出与稀缺判断的区别。节目呈现的是当时的推断，不把任何岗位消失视为已证实事实。"
        ]
      },
      {
        "heading": "把时间背景留在讨论里",
        "kind": "source",
        "paragraphs": [
          "开场明确提醒，AI 话题容易混合长期原则和短期变化。对工具的期待与限制应放回2026年2月，而不能让后来读者误以为谈话已掌握未来结果。"
        ]
      }
    ],
    "takeaway": "亲手使用工具能增加理解，但关于未来工作的推断仍有时间边界。",
    "references": [
      {
        "title": "Naval 官方网站｜原始页面",
        "url": "https://nav.al/ai"
      }
    ]
  },
