        "kind": "source",
        "paragraphs": [
          "文章将这个判断扩展到课程、视频与播客，并讨论重新识别真正受众、持续带来惊喜。因果归因仍是作者分析，销售变化本身不能单独证明全部下降由 AI 导致。"
        ]
