        "heading": "重要性与成功概率分别判断",
        "kind": "source",
        "paragraphs": [
          "谈到建立 SpaceX 的决定时，访谈将结果是否重要与项目是否容易成功分开。后半程又回到日常工作：工程团队、生产线和工厂占据大量注意力。宏大目标与具体工程劳动在这里并非两个互不相干的故事。"
        ]
