    "takeaway": "2012 年 4 月 30 日，美国东部时间上午 11 点 22 分，一枚猎鹰 9 号火箭要从卡纳维拉尔角升空。它的货舱里装着一艘名叫龙飞船（Dragon）的太空船，目的地是 400 公里高的国际空间站。",
